1058: function rowIdsOf(art: Art): string[] {
1059:   if (art.meta?.excelGrid) {
1060:     const rowCount = Math.max(1, Number(art.meta.excelGrid.rows) || 1);
1061:     return Array.from({ length: rowCount }, (_, i) => String(i + 1));
1062:   }
1063:   // Fresh-room sheets can briefly receive their element map before the small
1064:   // version/order companion query. They also become mixed-address artifacts
1065:   // when NodeAgent writes canonical A1 cells beside the legacy rN__column
1066:   // seed. The declared blank-sheet extent is authoritative in both cases.
1067:   const blankRows = isBlankSpreadsheet(art) ? dataframeRowCount(art) : 0;
1068:   if (blankRows) return Array.from({ length: blankRows }, (_, i) => String(i + 1));
1069:   const ids: string[] = [];
1070:   const elementIds = (art.order?.length ? art.order : Object.keys(art.elements ?? {}));
1071:   for (const eid of elementIds) {
1072:     const a1 = eid.match(/^[A-Z]+(\d+)$/);
1073:     const r = a1?.[1] ?? eid.split("__")[0];
1074:     if (r && !ids.includes(r)) ids.push(r);
1075:   }
1076:   return ids;
1077: }
